import openpyxl
from openpyxl.utils import get_column_letter
wb = openpyxl.load_workbook('task/init.xlsx')
ws = wb['Sheet1']
styles=set()
for r in range(1, ws.max_row+1):
    for c in range(1, ws.max_column+1):
        cell = ws.cell(r,c)
        b = cell.border
        for s in (b.left,b.right,b.top,b.bottom):
            if s and s.style:
                styles.add(s.style)
print("all border styles used:", styles)
# find cells with non-medium style
for r in range(1, ws.max_row+1):
    for c in range(1, ws.max_column+1):
        cell = ws.cell(r,c)
        b = cell.border
        for name,s in (('L',b.left),('R',b.right),('T',b.top),('B',b.bottom)):
            if s and s.style and s.style!='medium':
                print(f"{get_column_letter(c)}{r} {name}={s.style} val={cell.value!r}")
EOF
